{
  "description": "The creature is a quadrupedal animal shown in right-facing profile with the overall body shape, fur, head, limbs and posture of a brown bear but bearing glossy dark beetle-like exoskeleton structures. It has shaggy brown fur that is darker on the back and limbs and lighter tan on the muzzle, chest and underside, four thick clawed legs in a walking stride, a short rounded tail at the rear, small rounded ears on top of the head, and a single long glossy black horn curving up and back from the forehead. Its back from the shoulders to the rump is covered by four large overlapping shiny dark brown to black dorsal plates, with additional ridged segmented plating along the lower side and two large oval elytra-like shells covering the shoulder and hip areas.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense shaggy brown fur, a lighter tan muzzle, a large black nose at the tip, small brown eyes, and a closed mouth, located at the front of the body facing to the right"
    ,
      "where": "front of body"
    },
    {
      "part": "horns",
      "looks_like": "single long glossy black horn with a smooth curved shape sweeping upward and backward, tapering to a sharp point, with a small pointed notch on the inner curve near the tip",
      "where": "rising vertically from the forehead on top of the head"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in brown fur",
      "where": "on top of the head behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in long shaggy dark brown fur",
      "where": "under the body, two forelegs and two hindlegs in a walking stance"
    },
    {
      "part": "feet",
      "looks_like": "four large bear paws with blunt dark claws and visible pads on the soles",
      "where": "at the ends of the four legs on the ground"
    },
    {
      "part": "tail",
      "looks_like": "short small rounded tail covered in brown fur",
      "where": "at the rear of the body above the hind legs"
    },
    {
      "part": "plates",
      "looks_like": "four large overlapping glossy dark brown to black dorsal plates with fine horizontal ridging and a raised pointed crest on the shoulder plate, plus a row of smaller ridged brown segmented plates with circular openings along the lower flank",
      "where": "covering the dorsal midline from the shoulders to the rump and along the side of the torso"
    },
    {
      "part": "shell",
      "looks_like": "two large oval glossy dark brown elytra-like shells with vertical ridges and a distinct central seam, shiny and hard-looking",
      "where": "on the lateral sides of the body, one over the shoulder/foreleg and one over the hip/hindleg"
    },
    {
      "part": "markings",
      "looks_like": "lighter tan to beige fur on the chest, throat and underside contrasting with darker brown fur on the back, head and outer limbs",
      "where": "on the ventral chest and belly area and on the muzzle"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
